import type { Route } from './+types/sitemap';
import { logRequest } from '../server/logging';
import { getBackendBaseUrl, getBackendHeaders } from '../server/bff/proxy';
import { getRequestOrigin } from '../utils/requestMeta';

// Resource route: the sitemap is generated by the backend; proxied like the BFF.
export async function loader({ request, context }: Route.LoaderArgs) {
  const start = Date.now();
  const origin = getRequestOrigin(request);
  const baseUrl = getBackendBaseUrl(origin);
  // Append, not resolve: keeps a base path such as /functions/v1/api.
  const url = `${baseUrl.replace(/\/+$/, '')}/sitemap.xml`;
  const headers = {
    ...getBackendHeaders(request, origin, context.requestId),
    Accept: 'application/xml',
  };
  const logFields = { kind: 'sitemap', method: 'GET', path: '/sitemap.xml' };

  try {
    const response = await fetch(url, {
      headers,
      // Never follow a redirect with the origin secret; bound the wait.
      redirect: 'manual',
      signal: AbortSignal.timeout(8000),
    });
    if (response.status >= 300 && response.status < 400) {
      throw new Error(`Unexpected upstream redirect (${response.status})`);
    }
    const body = await response.text();
    logRequest(
      {
        ...logFields,
        status: response.status,
        duration_ms: Date.now() - start,
      },
      context.requestId
    );
    return new Response(body, {
      status: response.status,
      headers: {
        // The Supabase gateway rewrites application/xml to text/plain.
        'Content-Type': response.ok
          ? 'application/xml'
          : response.headers.get('content-type') || 'text/plain',
        'Cache-Control': 'public, max-age=43200',
      },
    });
  } catch (error) {
    logRequest(
      {
        ...logFields,
        status: 502,
        duration_ms: Date.now() - start,
        error: error instanceof Error ? error.message : String(error),
      },
      context.requestId
    );
    return new Response('Bad Gateway', {
      status: 502,
      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
    });
  }
}
